    + (low ? '<div class="card"><strong>Para pedir</strong>' + lines((report.low_stock || []).slice(0, 4), function (r) { return r.name; }, function (r) { return qty(r.stock) + " / m\xEDn " + qty(r.min_stock); }) + "</div>" : "")
